eval("__webpack_require__.r(__webpack_exports__);\n/* harmony export */ __webpack_require__.d(__webpack_exports__, {\n/* harmony export */   blogCategories: () => (/* binding */ blogCategories),\n/* harmony export */   blogPosts: () => (/* binding */ blogPosts),\n/* harmony export */   getPost: () => (/* binding */ getPost)\n/* harmony export */ });\nconst blogCategories = [\n    \"FSc Chemistry\",\n    \"MDCAT Preparation\",\n    \"ECAT Preparation\",\n    \"Chemistry Concepts\",\n    \"Fundamentals of Chemistry\",\n    \"Exam Preparation\",\n    \"Study Techniques\",\n    \"Educational Updates\"\n];\nconst blogPosts = [\n    {\n        slug: \"balancing-chemical-equations-step-by-step\",\n        title: \"Balancing Chemical Equations: A Step-by-Step Method\",\n        excerpt: \"A clear, repeatable method for balancing any chemical equation — the skill that underpins stoichiometry, MDCAT MCQs and FSc numericals.\",\n        category: \"Chemistry Concepts\",\n        date: \"2025-09-18\",\n        readingTime: \"6 min read\",\n        author: \"Professor Noor Saleem\",\n        body: [\n            {\n                type: \"p\",\n                text: \"Balancing chemical equations is one of the first skills every Chemistry student must master. It is not just a bookkeeping exercise — it is the foundation of stoichiometry, limiting-reactant problems and almost every numerical you will meet in FSc, MDCAT and ECAT.\"\n            },\n            {\n                type: \"p\",\n                text: \"The law of conservation of mass requires that the number of atoms of each element is the same on both sides of a chemical equation. This article gives you a method you can apply to any equation.\"\n            },\n            {\n                type: \"h2\",\n                text: \"The method in four steps\"\n            },\n            {\n                type: \"ol\",\n                items: [\n                    \"Write the correct formulae of all reactants and products. Never balance an equation by changing formulae — change only the coefficients.\",\n                    \"Count the atoms of each element on both sides.\",\n                    \"Balance one element at a time, starting with the most complex substance. Leave hydrogen and oxygen until last when possible.\",\n                    \"Check every element again and reduce the coefficients to the simplest whole-number ratio.\"\n                ]\n            },\n            {\n                type: \"h2\",\n                text: \"Worked example\"\n            },\n            {\n                type: \"p\",\n                text: \"Balance the combustion of propane:\"\n            },\n            {\n                type: \"equation\",\n                latex: \"\\\\text{C}_3\\\\text{H}_8 + \\\\text{O}_2 \\\\rightarrow \\\\text{CO}_2 + \\\\text{H}_2\\\\text{O}\",\n                caption: \"Unbalanced equation\"\n            },\n            {\n                type: \"p\",\n                text: \"Carbon appears in 3 atoms on the left and 1 on the right, so place a 3 before CO₂. Hydrogen appears in 8 atoms on the left and 2 on the right, so place a 4 before H₂O.\"\n            },\n            {\n                type: \"equation\",\n                latex: \"\\\\text{C}_3\\\\text{H}_8 + \\\\text{O}_2 \\\\rightarrow 3\\\\text{CO}_2 + 4\\\\text{H}_2\\\\text{O}\"\n            },\n            {\n                type: \"p\",\n                text: \"Now count oxygen on the right: 3\\xd72 + 4\\xd71 = 10 oxygen atoms. So we need 5 O₂ molecules on the left.\"\n            },\n            {\n                type: \"equation\",\n                latex: \"\\\\text{C}_3\\\\text{H}_8 + 5\\\\text{O}_2 \\\\rightarrow 3\\\\text{CO}_2 + 4\\\\text{H}_2\\\\text{O}\",\n                caption: \"Balanced equation\"\n            },\n            {\n                type: \"callout\",\n                variant: \"tip\",\n                title: \"Exam tip\",\n                text: \"In MDCAT MCQs, always check the simplest whole-number ratio. Coefficients of 2, 3 and 6 can usually be divided by 2 to give 1, 1.5 and 3 — but coefficients must be integers, so multiply through instead.\"\n            },\n            {\n                type: \"h2\",\n                text: \"Common mistakes\"\n            },\n            {\n                type: \"ul\",\n                items: [\n                    \"Changing subscripts inside a formula to force balance — this changes the substance itself.\",\n                    \"Forgetting to re-check after each change; balancing is iterative.\",\n                    \"Leaving fractional coefficients instead of multiplying through to clear them.\"\n                ]\n            },\n            {\n                type: \"p\",\n                text: \"Practise this method on ten equations from your textbook and it will become automatic. Once equations are balanced, stoichiometric ratios, limiting reactants and percentage-yield problems all follow directly.\"\n            }\n        ]\n    },\n    {\n        slug: \"mdcat-chemistry-high-yield-topics\",\n        title: \"MDCAT Chemistry: High-Yield Topics to Prioritise\",\n        excerpt: \"Not every topic carries equal weight in MDCAT. Here is how to focus your revision on the concepts and question types that appear most often.\",\n        category: \"MDCAT Preparation\",\n        date: \"2025-09-02\",\n        readingTime: \"7 min read\",\n        author: \"Professor Noor Saleem\",\n        body: [\n            {\n                type: \"p\",\n                text: \"MDCAT Chemistry is broad, but it is not equally weighted. Some topics appear in nearly every paper, while others are rarely tested. If your preparation time is limited, prioritising high-yield topics is the single most effective strategy.\"\n            },\n            {\n                type: \"h2\",\n                text: \"Physical Chemistry — the backbone\"\n            },\n            {\n                type: \"p\",\n                text: \"Stoichiometry, atomic structure, chemical bonding and electrochemistry together account for a large share of MDCAT Chemistry marks. Master mole calculations, quantum numbers, hybridisation and the electrochemical series first.\"\n            },\n            {\n                type: \"callout\",\n                variant: \"definition\",\n                title: \"Key definition\",\n                text: \"The mole is the amount of substance that contains 6.022 \\xd7 10\\xb2\\xb3 elementary particles — Avogadro's number.\"\n            },\n            {\n                type: \"h2\",\n                text: \"Organic Chemistry — reactions and identification\"\n            },\n            {\n                type: \"p\",\n                text: \"Organic chemistry tests your recall of functional-group reactions and identification tests. Focus on the reactions of alcohols, aldehydes, ketones and carboxylic acids, and on the characteristic tests (Tollens, Fehling, Lucas test, iodoform).\"\n            },\n            {\n                type: \"h2\",\n                text: \"Inorganic Chemistry — periodic trends\"\n            },\n            {\n                type: \"p\",\n                text: \"Periodic trends — atomic radius, ionisation energy, electron affinity and electronegativity — underpin many MDCAT questions. Understand the trends and their exceptions rather than memorising isolated facts.\"\n            },\n            {\n                type: \"callout\",\n                variant: \"warning\",\n                title: \"Common mistake\",\n                text: \"Students often memorise reactions without understanding why they happen. MDCAT questions frequently test the reasoning, not just the product.\"\n            },\n            {\n                type: \"h2\",\n                text: \"A practical revision plan\"\n            },\n            {\n                type: \"ol\",\n                items: [\n                    \"Spend 50% of your time on Physical Chemistry, 30% on Organic, 20% on Inorganic.\",\n                    \"Do topic-wise MCQs immediately after revising each topic.\",\n                    \"Take one full-length Chemistry test every week in the final month.\",\n                    \"Review every incorrect answer and write down the concept you missed.\"\n                ]\n            },\n            {\n                type: \"p\",\n                text: \"Concentrating on high-yield topics does not mean ignoring the rest — it means making sure the most important concepts are automatic before you move on to lower-yield material.\"\n            }\n        ]\n    },\n    {\n        slug: \"how-to-study-chemistry-numericals\",\n        title: \"How to Study Chemistry Numericals Without Memorising\",\n        excerpt: \"Numericals scare many students, but they become straightforward once you treat them as concept applications, not formula recall.\",\n        category: \"Study Techniques\",\n        date: \"2025-08-21\",\n        readingTime: \"5 min read\",\n        author: \"Professor Noor Saleem\",\n        body: [\n            {\n                type: \"p\",\n                text: \"Many students approach Chemistry numericals by memorising formulae and plugging in values. This works for simple questions but fails the moment an exam rephrases the problem. The reliable approach is to understand the concept, derive the relationship, and only then calculate.\"\n            },\n            {\n                type: \"h2\",\n                text: \"A four-step framework\"\n            },\n            {\n                type: \"ol\",\n                items: [\n                    \"Read the question twice and write down what is given and what is asked, with units.\",\n                    \"Identify the concept — is this stoichiometry, gas law, thermochemistry, equilibrium?\",\n                    \"Write the relevant relationship and rearrange it symbolically before substituting numbers.\",\n                    \"Substitute with units, calculate, and check whether the answer is physically reasonable.\"\n                ]\n            },\n            {\n                type: \"callout\",\n                variant: \"tip\",\n                title: \"Why this works\",\n                text: \"When you rearrange symbolically, you catch unit errors before they hide in the arithmetic. When you check the reasonableness of the answer, you catch mistakes that pure calculation would miss.\"\n            },\n            {\n                type: \"h2\",\n                text: \"An example: limiting reactant\"\n            },\n            {\n                type: \"p\",\n                text: \"Suppose 5.0 g of hydrogen reacts with 32 g of oxygen to form water. Which is the limiting reactant?\"\n            },\n            {\n                type: \"equation\",\n                latex: \"2\\\\text{H}_2 + \\\\text{O}_2 \\\\rightarrow 2\\\\text{H}_2\\\\text{O}\"\n            },\n            {\n                type: \"p\",\n                text: \"Moles of H₂ = 5.0 / 2 = 2.5 mol. Moles of O₂ = 32 / 32 = 1.0 mol. The equation needs 2 mol H₂ per 1 mol O₂, so 2.5 mol H₂ would need 1.25 mol O₂ — but only 1.0 mol is available. Oxygen is the limiting reactant.\"\n            },\n            {\n                type: \"p\",\n                text: 'Notice that we never memorised a \"limiting reactant formula\". We used the balanced equation and the mole concept, which is exactly how the examiner expects you to think.'\n            }\n        ]\n    }\n];\nfunction getPost(slug) {\n    return blogPosts.find((p)=>p.slug === slug);\n}\n//# sourceURL=[module]\n//# sourceMappingURL=data:application/json;charset=utf-8;base64,\n//# sourceURL=webpack-internal:///(rsc)/./src/data/blog.ts\n");

